typedef enum { J_NULL, J_BOOL, J_NUMBER, J_STRING, J_ARRAY, J_OBJECT } JsonType;

typedef struct JsonValue JsonValue;
struct JsonValue {
  JsonType type;
  int boolean;
  double number;
  char *string;
  JsonValue **items;
  char **keys;
  int count;
  int capacity;
};

typedef struct {
  char *key;
  JsonValue *value;
} Entry;

JsonValue *json_new(JsonType type) {
  JsonValue *v = calloc(1, sizeof(JsonValue));
  v->type = type;
  return v;
}

void json_free(JsonValue *v) {
  if (!v) return;
  if (v->type == J_STRING) {
    free(v->string);
  }
  if (v->type == J_ARRAY || v->type == J_OBJECT) {
    for (int i = 0; i < v->count; i++) {
      json_free(v->items[i]);
      if (v->type == J_OBJECT) free(v->keys[i]);
    }
    free(v->items);
    if (v->type == J_OBJECT) free(v->keys);
  }
  free(v);
}

JsonValue *deep_copy(JsonValue *v) {
  JsonValue *res = json_new(v->type);
  res->boolean = v->boolean;
  res->number = v->number;
  if (v->type == J_STRING) {
    res->string = strdup(v->string);
  }
  if (v->type == J_ARRAY || v->type == J_OBJECT) {
    res->count = v->count;
    res->capacity = v->count > 0 ? v->count : 1;
    res->items = calloc(res->capacity, sizeof(JsonValue*));
    if (v->type == J_OBJECT) {
      res->keys = calloc(res->capacity, sizeof(char*));
