func parseLine(_ line: String) -> LogEntry? {
    let str = line.trimmingCharacters(in: .whitespacesAndNewlines)
    if str.isEmpty { return nil }
    guard let openBracketRange = str.range(of: "["), let closeBracketRange = str.range(of: "]") else { return nil }
    let openBracketIndex = openBracketRange.lowerBound
    let closeBracketIndex = closeBracketRange.lowerBound
    let timeStr = String(str[str.index(after: openBracketIndex)..<closeBracketIndex])
    let afterBracket = String(str[str.index(after: closeBracketIndex)...]).trimmingCharacters(in: .whitespaces)
    guard let openParenRange = afterBracket.range(of: "("), let closeParenRange = afterBracket.range(of: ")") else { return nil }
    let openParenIndex = openParenRange.lowerBound
    let closeParenIndex = closeParenRange.lowerBound
    let level = String(afterBracket[afterBracket.startIndex..<openParenIndex]).trimmingCharacters(in: .whitespaces)
    let component = String(afterBracket[afterBracket.index(after: openParenIndex)..<closeParenIndex]).trimmingCharacters(in: .whitespaces)
    var msgPart = String(afterBracket[afterBracket.index(after: closeParenIndex)..<afterBracket.endIndex])
    if let dashRange = msgPart.range(of: " - ") {
        msgPart = String(msgPart[msgPart.index(after: dashRange.upperBound)..<msgPart.endIndex])
    } else if msgPart.hasPrefix("- ") {
        msgPart = String(msgPart.dropFirst(2))
    }
    msgPart = msgPart.trimmingCharacters(in: .whitespaces)
    let timeParts = timeStr.split(separator: " ")
    let timeOnly = timeParts.count > 1 ? String(timeParts[1]) : ""
