def main():
    graph_path = "__FIXTURE_DIR__/graph.json"
    with open(graph_path, "r") as f:
        graph = json.load(f)

    nodes = graph.get("nodes", [])
    edges = graph.get("edges", [])

    adj = {node: [] for node in nodes}
    for edge in edges:
        u = edge["from"]
        v = edge["to"]
        w = edge["weight"]
        adj[u].append((v, w))
        adj[v].append((u, w))

    start = "A"
    dist = {node: float("inf") for node in nodes}
    dist[start] = 0
    pq = [(0, start)]
    visited = set()

    while pq:
        d, u = heapq.heappop(pq)
        if u in visited:
            continue
        visited.add(u)

        for v, w in adj.get(u, []):
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))

    print("=== Shortest Paths from A ===")
    print()
    for node in sorted(nodes):
        d = dist.get(node, float("inf"))
        if d == float("inf"):
            print(f"{start} -> {node}: inf")
        else:
            print(f"{start} -> {node}: {int(d)}")

