import { readFileSync } from "fs";

interface Edge {
  from: string;
  to: string;
  weight: number;
}

interface Graph {
  nodes: string[];
  edges: Edge[];
}

function main(): void {
  const raw: string = readFileSync("__FIXTURE_DIR__/graph.json", "utf8");
  const graph: Graph = JSON.parse(raw);

  const adj: { [key: string]: { to: string; weight: number }[] } = {};
  for (let i = 0; i < graph.nodes.length; i++) {
    const n = graph.nodes[i];
    adj[n] = [];
  }

  for (let i = 0; i < graph.edges.length; i++) {
    const e = graph.edges[i];
    if (!adj[e.from]) {
      adj[e.from] = [];
    }
    if (!adj[e.to]) {
      adj[e.to] = [];
    }
    adj[e.from].push({ to: e.to, weight: e.weight });
    adj[e.to].push({ to: e.from, weight: e.weight });
  }

  const dist: { [key: string]: number } = {};
  for (let i = 0; i < graph.nodes.length; i++) {
    const n = graph.nodes[i];
    dist[n] = Infinity;
  }
  dist["A"] = 0;

  const visited: { [key: string]: boolean } = {};

  while (true) {
    let current: string | null = null;
    let best: number = Infinity;

    for (let i = 0; i < graph.nodes.length; i++) {
      const n = graph.nodes[i];
      if (!visited[n] && dist[n] < best) {
        best = dist[n];
        current = n;
      }
    }

    if (current === null) {
      break;
    }
    if (best === Infinity) {
      break;
    }

    visited[current] = true;
    const neighbors = adj[current] || [];
    for (let j = 0; j < neighbors.length; j++) {
      const e = neighbors[j];
      const alt = dist[current] + e.weight;
      if (alt < dist[e.to]) {
        dist[e.to] = alt;
      }
    }
  }

  const sortedNodes: string[] = graph.nodes.slice();
  sortedNodes.sort();

  console.log("=== Shortest Paths from A ===");
  console.log();
  for (let i = 0; i < sortedNodes.length; i++) {
    const n = sortedNodes[i];
    const d = dist[n];
    console.log(`A -> ${n}: ${d === Infinity ? "Infinity" : d}`);
  }
}

