function countLines(buffer: any): number {
  if (buffer.length === 0) return 0;
  const content = buffer.toString('utf8');
  const normalized = content.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  const lines = normalized.split('\n');
  if (normalized.endsWith('\n')) {
    lines.pop();
  }
  return lines.length;
}

function walk(dir: string, base: string): FileInfo[] {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  const files: FileInfo[] = [];
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...walk(fullPath, base));
    } else if (entry.isFile()) {
      const buffer = fs.readFileSync(fullPath);
      const relativePath = path.relative(base, fullPath).split(path.sep).join('/');
      files.push({ relativePath, lines: countLines(buffer), chars: buffer.length });
    }
  }
  return files;
}

