func collectFiles(in url: URL, relativeTo parent: String = "") -> [FileInfo] {
    var results: [FileInfo] = []
    guard let entries = try? FileManager.default.contentsOfDirectory(
        at: url,
        includingPropertiesForKeys: [.isSymbolicLinkKey, .isDirectoryKey]
    ) else {
        return results
    }

    for entry in entries {
        let child = url.appendingPathComponent(entry)
        let relativePath = parent.isEmpty ? entry : parent + "/" + entry

        var isSymlink = false
        var isDirectory = false
        if let properties = try? child.resourceValues(forKeys: [.isSymbolicLinkKey, .isDirectoryKey]) {
            isSymlink = properties.isSymbolicLink ?? false
            isDirectory = properties.isDirectory ?? false
        }

        if isSymlink { continue }

        if isDirectory {
            results.append(contentsOf: collectFiles(in: child, relativeTo: relativePath))
        } else {
            var lineCount = 0
            var charCount = 0
            if let data = try? Data(contentsOf: child) {
                charCount = data.count
                var lastByte: UInt8 = 0
                if let last = data.last {
                    lastByte = last
                }
                for byte in data where byte == 0x0A {
                    lineCount += 1
                }
                if !data.isEmpty && lastByte != 0x0A {
                    lineCount += 1
                }
            }
            results.append(FileInfo(relativePath: relativePath, lineCount: lineCount, charCount: charCount))
        }
    }

    return results
}

