const A: number[][] = [
  [1, 2, 3],
  [4, 5, 6],
  [7, 8, 9]
];

const B: number[][] = [
  [9, 8, 7],
  [6, 5, 4],
  [3, 2, 1]
];

function multiply(A: number[][], B: number[][]): number[][] {
  const n = A.length;
  const m = B[0].length;
  const p = A[0].length;
  const C: number[][] = [];
  for (let i = 0; i < n; i++) {
    const row: number[] = [];
    for (let j = 0; j < m; j++) {
      row.push(0);
    }
    C.push(row);
  }
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      let sum = 0;
      for (let k = 0; k < p; k++) {
        sum += A[i][k] * B[k][j];
      }
      C[i][j] = sum;
    }
  }
  return C;
}

function determinant(M: number[][]): number {
  const n = M.length;
  if (n === 1) return M[0][0];
  if (n === 2) return M[0][0] * M[1][1] - M[0][1] * M[1][0];
  let det = 0;
  for (let col = 0; col < n; col++) {
    const sub: number[][] = [];
    for (let r = 1; r < n; r++) {
      const row: number[] = [];
      for (let c = 0; c < n; c++) {
        if (c === col) continue;
        row.push(M[r][c]);
      }
      sub.push(row);
    }
    const sign = col % 2 === 0 ? 1 : -1;
    det += sign * M[0][col] * determinant(sub);
  }
  return det;
}

function formatMatrix(M: number[][]): string[] {
  return M.map(row => {
    const parts: string[] = [];
    for (let i = 0; i < row.length; i++) {
      let val = row[i].toString();
      while (val.length < 4) {
        val = " " + val;
      }
      parts.push(val);
    }
    return "  " + parts.join(" ");
  });
}

